INSERT INTO modules (id, unit_id, order_index, slug, title, description, is_published) VALUES
('00000001-0000-0000-0000-000000000014','00000000-0000-0000-0001-000000000001',14,'comprension-auditiva','{"es": "Comprensión Auditiva", "en": "Listening Comprehension"}','{"es": "Practica tu comprensión auditiva en inglés escuchando saludos, números, preguntas, familia, comida y mucho más — todo vocabulario y gramática que ya aprendiste.", "en": "Practice your English listening comprehension by hearing greetings, numbers, questions, family, food, and more — all vocabulary and grammar you''ve already learned."}',true),
('00000001-0000-0000-0000-000000000015','00000000-0000-0000-0001-000000000001',15,'produccion-oral','{"es": "Producción Oral", "en": "Speaking Production"}','{"es": "Practica tu pronunciación diciendo en voz alta presentaciones, preguntas, respuestas y frases que ya aprendiste.", "en": "Practice your pronunciation by saying introductions, questions, answers, and phrases you''ve already learned out loud."}',true);
INSERT INTO lessons (id, module_id, unit_id, order_index, slug, title, description, lesson_type, xp_reward, estimated_minutes, theory_content, is_published) VALUES
('00000002-0000-0000-0014-000000000001', '00000001-0000-0000-0000-000000000014', '00000000-0000-0000-0001-000000000001', 1, 'letras-numeros-precios', '{"es": "Letras, Números y Precios", "en": "Letters, Numbers, and Prices"}'::jsonb, '{"es": "Practica reconociendo letras deletreadas, números y precios al escucharlos.", "en": "Practice recognizing spelled letters, numbers, and prices by ear."}'::jsonb, 'listening', 30, 12, '{"intro": "En esta lección vas a escuchar letras y números que ya conoces del alfabeto y de los números en inglés. No hay vocabulario nuevo — el objetivo es entrenar tu oído para reconocer lo que ya sabes leer.", "sections": [{"type": "note", "variant": "tip", "text": "Esta lección es 100% práctica de comprensión auditiva — no presenta vocabulario ni gramática nueva. Puedes escuchar cada audio las veces que necesites antes de responder."}]}'::jsonb, true);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0014-0001-0001-000000000001', '00000002-0000-0000-0014-000000000001', 1, 'listening', '{"text": "Escucha la letra y escríbela.", "audio_text": "B"}'::jsonb, '{"text": "B", "accepted": ["B", "b"]}'::jsonb, NULL, NULL),
('00000003-0014-0001-0002-000000000001', '00000002-0000-0000-0014-000000000001', 2, 'listening', '{"text": "Escucha la palabra y escríbela.", "audio_text": "cat"}'::jsonb, '{"text": "cat", "accepted": ["cat"]}'::jsonb, NULL, NULL),
('00000003-0014-0001-0003-000000000001', '00000002-0000-0000-0014-000000000001', 3, 'listening', '{"text": "Escucha el número y selecciona la cifra correcta.", "audio_text": "fifteen"}'::jsonb, '{"text": "15"}'::jsonb, '["50", "5", "115"]'::jsonb, '{"es": "''Fifteen'' (15) no debe confundirse con ''fifty'' (50) — el sonido final es distinto: -teen vs -ty."}'::jsonb),
('00000003-0014-0001-0004-000000000001', '00000002-0000-0000-0014-000000000001', 4, 'listening', '{"text": "Escucha el número y selecciona la cifra correcta.", "audio_text": "eighty-three"}'::jsonb, '{"text": "83"}'::jsonb, '["38", "93", "13"]'::jsonb, '{"es": "Cuidado con el orden: ''eighty-three'' es 83, no 38 — en inglés se dice primero la decena."}'::jsonb),
('00000003-0014-0001-0005-000000000001', '00000002-0000-0000-0014-000000000001', 5, 'listening', '{"text": "Escucha la frase y escríbela.", "audio_text": "How much is it?"}'::jsonb, '{"text": "How much is it?", "accepted": ["How much is it?", "How much is it"]}'::jsonb, NULL, NULL),
('00000003-0014-0001-0006-000000000001', '00000002-0000-0000-0014-000000000001', 6, 'listening', '{"text": "Escucha el precio y selecciona la opción correcta.", "audio_text": "seven dollars and fifty cents"}'::jsonb, '{"text": "$7.50"}'::jsonb, '["$70.50", "$7.15", "$17.50"]'::jsonb, NULL),
('00000003-0014-0001-0007-000000000001', '00000002-0000-0000-0014-000000000001', 7, 'listening', '{"text": "Escucha el número y escríbelo en palabras.", "audio_text": "twelve"}'::jsonb, '{"text": "twelve", "accepted": ["twelve"]}'::jsonb, NULL, NULL),
('00000003-0014-0001-0008-000000000001', '00000002-0000-0000-0014-000000000001', 8, 'listening', '{"text": "Escucha el ordinal y selecciona su significado.", "audio_text": "third"}'::jsonb, '{"text": "tercero / tercera"}'::jsonb, '["primero / primera", "séptimo / séptima", "treceavo / treceava"]'::jsonb, NULL);
INSERT INTO lessons (id, module_id, unit_id, order_index, slug, title, description, lesson_type, xp_reward, estimated_minutes, theory_content, is_published) VALUES
('00000002-0000-0000-0014-000000000002', '00000001-0000-0000-0000-000000000014', '00000000-0000-0000-0001-000000000001', 2, 'saludos-y-preguntas', '{"es": "Saludos y Preguntas", "en": "Greetings and Questions"}'::jsonb, '{"es": "Practica entendiendo saludos y preguntas básicas al escucharlos.", "en": "Practice understanding greetings and basic questions by ear."}'::jsonb, 'listening', 30, 12, '{"intro": "Vas a escuchar saludos y preguntas que ya aprendiste. Para las preguntas, en lugar de traducir, vas a elegir la respuesta apropiada — así practicas comprensión real, no solo traducción palabra por palabra.", "sections": [{"type": "note", "variant": "tip", "text": "Esta lección es 100% práctica de comprensión auditiva — no presenta vocabulario ni gramática nueva. Puedes escuchar cada audio las veces que necesites antes de responder."}]}'::jsonb, true);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0014-0002-0001-000000000001', '00000002-0000-0000-0014-000000000002', 1, 'listening', '{"text": "Escucha el saludo y selecciona su significado.", "audio_text": "Good morning"}'::jsonb, '{"text": "Buenos días"}'::jsonb, '["Buenas noches", "Buenas tardes", "Hola, ¿qué tal?"]'::jsonb, NULL),
('00000003-0014-0002-0002-000000000001', '00000002-0000-0000-0014-000000000002', 2, 'listening', '{"text": "Escucha la despedida y selecciona su significado.", "audio_text": "See you later!"}'::jsonb, '{"text": "¡Hasta luego!"}'::jsonb, '["¡Buenos días!", "¡Mucho gusto!", "¡De nada!"]'::jsonb, NULL),
('00000003-0014-0002-0003-000000000001', '00000002-0000-0000-0014-000000000002', 3, 'listening', '{"text": "Escucha la pregunta y selecciona la respuesta apropiada.", "audio_text": "What''s your name?"}'::jsonb, '{"text": "My name is Laura."}'::jsonb, '["I''m from Peru.", "I''m fine, thanks.", "See you later!"]'::jsonb, NULL),
('00000003-0014-0002-0004-000000000001', '00000002-0000-0000-0014-000000000002', 4, 'listening', '{"text": "Escucha la pregunta y selecciona la respuesta apropiada.", "audio_text": "Where are you from?"}'::jsonb, '{"text": "I''m from Brazil."}'::jsonb, '["My name is Carlos.", "I''m twenty years old.", "Nice to meet you."]'::jsonb, NULL),
('00000003-0014-0002-0005-000000000001', '00000002-0000-0000-0014-000000000002', 5, 'listening', '{"text": "Escucha la frase y escríbela.", "audio_text": "Nice to meet you"}'::jsonb, '{"text": "Nice to meet you", "accepted": ["Nice to meet you", "Nice to meet you too"]}'::jsonb, NULL, NULL),
('00000003-0014-0002-0006-000000000001', '00000002-0000-0000-0014-000000000002', 6, 'listening', '{"text": "Escucha la pregunta y selecciona la respuesta apropiada.", "audio_text": "How old are you?"}'::jsonb, '{"text": "I''m twenty-five years old."}'::jsonb, '["I''m from Mexico.", "My name is Ana.", "Good morning!"]'::jsonb, '{"es": "''How old are you?'' pregunta por la edad, así que la respuesta debe incluir un número de años, no un lugar ni un nombre."}'::jsonb),
('00000003-0014-0002-0007-000000000001', '00000002-0000-0000-0014-000000000002', 7, 'listening', '{"text": "Escucha la frase y selecciona su significado.", "audio_text": "Excuse me, where is the bank?"}'::jsonb, '{"text": "Perdón, ¿dónde está el banco?"}'::jsonb, '["Gracias por el banco.", "¿Cómo te llamas?", "De nada, banco."]'::jsonb, NULL),
('00000003-0014-0002-0008-000000000001', '00000002-0000-0000-0014-000000000002', 8, 'listening', '{"text": "Escucha la frase y escríbela.", "audio_text": "Thank you very much"}'::jsonb, '{"text": "Thank you very much", "accepted": ["Thank you very much", "Thank you very much."]}'::jsonb, NULL, NULL);
INSERT INTO lessons (id, module_id, unit_id, order_index, slug, title, description, lesson_type, xp_reward, estimated_minutes, theory_content, is_published) VALUES
('00000002-0000-0000-0014-000000000003', '00000001-0000-0000-0000-000000000014', '00000000-0000-0000-0001-000000000001', 3, 'familia-y-descripciones', '{"es": "La Familia y las Descripciones", "en": "Family and Descriptions"}'::jsonb, '{"es": "Practica entendiendo descripciones de familia, personas y objetos al escucharlas.", "en": "Practice understanding descriptions of family, people, and objects by ear."}'::jsonb, 'listening', 30, 12, '{"intro": "Ahora vas a escuchar oraciones completas sobre familia, colores y adjetivos. Presta atención a detalles como el género (he/she) y los números, ya que las opciones incorrectas suelen cambiar solo un detalle pequeño.", "sections": [{"type": "note", "variant": "tip", "text": "Esta lección es 100% práctica de comprensión auditiva — no presenta vocabulario ni gramática nueva. Puedes escuchar cada audio las veces que necesites antes de responder."}]}'::jsonb, true);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0014-0003-0001-000000000001', '00000002-0000-0000-0014-000000000003', 1, 'listening', '{"text": "Escucha la oración y selecciona su significado.", "audio_text": "My grandmother is eighty years old."}'::jsonb, '{"text": "Mi abuela tiene ochenta años."}'::jsonb, '["Mi abuelo tiene ochenta años.", "Mi madre tiene dieciocho años.", "Mi abuela tiene dieciocho años."]'::jsonb, NULL),
('00000003-0014-0003-0002-000000000001', '00000002-0000-0000-0014-000000000003', 2, 'listening', '{"text": "Escucha la oración y selecciona su significado.", "audio_text": "I have two brothers and one sister."}'::jsonb, '{"text": "Tengo dos hermanos y una hermana."}'::jsonb, '["Tengo una hermana y dos hermanos menores.", "Tengo dos hermanas y un hermano.", "No tengo hermanos."]'::jsonb, NULL),
('00000003-0014-0003-0003-000000000001', '00000002-0000-0000-0014-000000000003', 3, 'listening', '{"text": "Escucha la oración y selecciona su significado.", "audio_text": "She has brown eyes and blond hair."}'::jsonb, '{"text": "Ella tiene ojos cafés y cabello rubio."}'::jsonb, '["Ella tiene ojos azules y cabello negro.", "Él tiene ojos cafés y cabello rubio.", "Ella tiene ojos verdes y cabello rubio."]'::jsonb, NULL),
('00000003-0014-0003-0004-000000000001', '00000002-0000-0000-0014-000000000003', 4, 'listening', '{"text": "Escucha la palabra y escríbela.", "audio_text": "sister"}'::jsonb, '{"text": "sister", "accepted": ["sister"]}'::jsonb, NULL, NULL),
('00000003-0014-0003-0005-000000000001', '00000002-0000-0000-0014-000000000003', 5, 'listening', '{"text": "Escucha la palabra y escríbela.", "audio_text": "grandfather"}'::jsonb, '{"text": "grandfather", "accepted": ["grandfather"]}'::jsonb, NULL, NULL),
('00000003-0014-0003-0006-000000000001', '00000002-0000-0000-0014-000000000003', 6, 'listening', '{"text": "Escucha la oración y selecciona su significado.", "audio_text": "My dad is a doctor. He is very smart."}'::jsonb, '{"text": "Mi papá es doctor. Él es muy inteligente."}'::jsonb, '["Mi papá es doctor. Ella es muy inteligente.", "Mi mamá es doctora. Él es muy inteligente.", "Mi papá es ingeniero. Él es muy amable."]'::jsonb, '{"es": "''He'' se refiere a ''my dad'' (masculino) — la oración no cambia de sujeto a ''mom'' ni de pronombre a ''she''."}'::jsonb),
('00000003-0014-0003-0007-000000000001', '00000002-0000-0000-0014-000000000003', 7, 'listening', '{"text": "Escucha la oración y selecciona su significado.", "audio_text": "The table is square and small."}'::jsonb, '{"text": "La mesa es cuadrada y pequeña."}'::jsonb, '["La mesa es redonda y grande.", "La silla es cuadrada y pequeña.", "La mesa es cuadrada y grande."]'::jsonb, NULL),
('00000003-0014-0003-0008-000000000001', '00000002-0000-0000-0014-000000000003', 8, 'listening', '{"text": "Escucha la oración y selecciona su significado.", "audio_text": "My friend is tall and friendly."}'::jsonb, '{"text": "Mi amigo es alto y simpático."}'::jsonb, '["Mi amigo es bajo y simpático.", "Mi amiga es alta y simpática.", "Mi amigo es alto y serio."]'::jsonb, NULL);
INSERT INTO lessons (id, module_id, unit_id, order_index, slug, title, description, lesson_type, xp_reward, estimated_minutes, theory_content, is_published) VALUES
('00000002-0000-0000-0014-000000000004', '00000001-0000-0000-0000-000000000014', '00000000-0000-0000-0001-000000000001', 4, 'comida-y-el-cuerpo', '{"es": "Comida y el Cuerpo", "en": "Food and the Body"}'::jsonb, '{"es": "Practica entendiendo frases de restaurante y de salud al escucharlas.", "en": "Practice understanding restaurant and health phrases by ear."}'::jsonb, 'listening', 30, 12, '{"intro": "En esta lección escucharás frases de restaurante y de salud que ya conoces. Algunas opciones incorrectas describen un síntoma o pedido distinto — escucha con atención cada palabra clave.", "sections": [{"type": "note", "variant": "tip", "text": "Esta lección es 100% práctica de comprensión auditiva — no presenta vocabulario ni gramática nueva. Puedes escuchar cada audio las veces que necesites antes de responder."}]}'::jsonb, true);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0014-0004-0001-000000000001', '00000002-0000-0000-0014-000000000004', 1, 'listening', '{"text": "Escucha la pregunta y selecciona su significado.", "audio_text": "Can I have a coffee, please?"}'::jsonb, '{"text": "¿Me puede dar un café, por favor?"}'::jsonb, '["¿Puedo tomar café?", "¿Tiene café?", "¿Le gusta el café?"]'::jsonb, NULL),
('00000003-0014-0004-0002-000000000001', '00000002-0000-0000-0014-000000000004', 2, 'listening', '{"text": "Escucha la frase y selecciona su significado.", "audio_text": "I love it!"}'::jsonb, '{"text": "¡Me encanta!"}'::jsonb, '["Lo odio.", "Está bien.", "No me gusta."]'::jsonb, NULL),
('00000003-0014-0004-0003-000000000001', '00000002-0000-0000-0014-000000000004', 3, 'listening', '{"text": "Escucha la oración y selecciona su significado.", "audio_text": "I have a headache and a fever."}'::jsonb, '{"text": "Tengo dolor de cabeza y fiebre."}'::jsonb, '["Tengo dolor de estómago y tos.", "Tengo fiebre y estoy cansado.", "Tengo dolor de cabeza y estoy mareado."]'::jsonb, NULL),
('00000003-0014-0004-0004-000000000001', '00000002-0000-0000-0014-000000000004', 4, 'listening', '{"text": "Escucha la palabra y escríbela.", "audio_text": "cheese"}'::jsonb, '{"text": "cheese", "accepted": ["cheese"]}'::jsonb, NULL, NULL),
('00000003-0014-0004-0005-000000000001', '00000002-0000-0000-0014-000000000004', 5, 'listening', '{"text": "Escucha la palabra y escríbela.", "audio_text": "shoulder"}'::jsonb, '{"text": "shoulder", "accepted": ["shoulder"]}'::jsonb, NULL, NULL),
('00000003-0014-0004-0006-000000000001', '00000002-0000-0000-0014-000000000004', 6, 'listening', '{"text": "Escucha la oración y selecciona su significado.", "audio_text": "My stomach hurts."}'::jsonb, '{"text": "Me duele el estómago."}'::jsonb, '["Me duele la cabeza.", "Me duele el hombro.", "Tengo hambre."]'::jsonb, NULL),
('00000003-0014-0004-0007-000000000001', '00000002-0000-0000-0014-000000000004', 7, 'listening', '{"text": "Escucha la pregunta y selecciona su significado.", "audio_text": "Can we have the bill, please?"}'::jsonb, '{"text": "¿Nos puede traer la cuenta, por favor?"}'::jsonb, '["¿Cuánto cuesta el café?", "¿Tiene la carta del menú?", "¿Dónde está el baño?"]'::jsonb, NULL),
('00000003-0014-0004-0008-000000000001', '00000002-0000-0000-0014-000000000004', 8, 'listening', '{"text": "Escucha la oración y selecciona su significado.", "audio_text": "I''d like to make an appointment with the doctor."}'::jsonb, '{"text": "Quisiera hacer una cita con el doctor."}'::jsonb, '["Quisiera una receta médica.", "Quisiera cancelar mi cita.", "Quisiera ver al doctor ahora mismo."]'::jsonb, NULL);
INSERT INTO lessons (id, module_id, unit_id, order_index, slug, title, description, lesson_type, xp_reward, estimated_minutes, theory_content, is_published) VALUES
('00000002-0000-0000-0014-000000000005', '00000001-0000-0000-0000-000000000014', '00000000-0000-0000-0001-000000000001', 5, 'repaso-auditivo-general', '{"es": "Repaso Auditivo General", "en": "General Listening Review"}'::jsonb, '{"es": "Repasa con el oído toda la gramática A1: to be, there is/are, do/does, can y más.", "en": "Review all A1 grammar by ear: to be, there is/are, do/does, can, and more."}'::jsonb, 'listening', 30, 12, '{"intro": "Esta última lección de escucha combina toda la gramática que aprendiste en el curso: to be, there is/are, do/does, can, y preguntas WH-. Es el repaso final de comprensión auditiva del nivel A1.", "sections": [{"type": "note", "variant": "tip", "text": "Esta lección es 100% práctica de comprensión auditiva — no presenta vocabulario ni gramática nueva. Puedes escuchar cada audio las veces que necesites antes de responder."}]}'::jsonb, true);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0014-0005-0001-000000000001', '00000002-0000-0000-0014-000000000005', 1, 'listening', '{"text": "Escucha la pregunta y selecciona su significado.", "audio_text": "Is there a pharmacy near here?"}'::jsonb, '{"text": "¿Hay una farmacia cerca de aquí?"}'::jsonb, '["Hay una farmacia cerca de aquí.", "¿Dónde está la farmacia?", "No hay farmacia aquí."]'::jsonb, '{"es": "Cuando ''is'' va antes de ''there'', es una pregunta: ''Is there...?'' = ¿Hay...?"}'::jsonb),
('00000003-0014-0005-0002-000000000001', '00000002-0000-0000-0014-000000000005', 2, 'listening', '{"text": "Escucha la oración y selecciona su significado.", "audio_text": "There are three books on the table."}'::jsonb, '{"text": "Hay tres libros en la mesa."}'::jsonb, '["Hay un libro en la mesa.", "Hay tres mesas con libros.", "No hay libros en la mesa."]'::jsonb, NULL),
('00000003-0014-0005-0003-000000000001', '00000002-0000-0000-0014-000000000005', 3, 'listening', '{"text": "Escucha la pregunta y selecciona la respuesta corta correcta.", "audio_text": "Do you like coffee?"}'::jsonb, '{"text": "Yes, I do."}'::jsonb, '["Yes, I am.", "Yes, I can.", "Yes, there is."]'::jsonb, '{"es": "La respuesta corta repite el auxiliar de la pregunta: ''Do...?'' se responde con ''I do.''"}'::jsonb),
('00000003-0014-0005-0004-000000000001', '00000002-0000-0000-0014-000000000005', 4, 'listening', '{"text": "Escucha la pregunta y selecciona la respuesta corta correcta.", "audio_text": "Can you swim?"}'::jsonb, '{"text": "Yes, I can."}'::jsonb, '["Yes, I do.", "Yes, I am.", "Yes, there are."]'::jsonb, '{"es": "''Can'' se responde con ''can'', no con ''do'' ni ''am''."}'::jsonb),
('00000003-0014-0005-0005-000000000001', '00000002-0000-0000-0014-000000000005', 5, 'listening', '{"text": "Escucha la instrucción y escríbela.", "audio_text": "Open the door, please."}'::jsonb, '{"text": "Open the door, please.", "accepted": ["Open the door, please.", "Open the door, please"]}'::jsonb, NULL, NULL),
('00000003-0014-0005-0006-000000000001', '00000002-0000-0000-0014-000000000005', 6, 'listening', '{"text": "Escucha la pregunta y selecciona la respuesta apropiada.", "audio_text": "Where do you live?"}'::jsonb, '{"text": "I live in Bogotá."}'::jsonb, '["My name is Bogotá.", "I am Bogotá.", "I can live in Bogotá."]'::jsonb, NULL),
('00000003-0014-0005-0007-000000000001', '00000002-0000-0000-0014-000000000005', 7, 'listening', '{"text": "Escucha la oración y selecciona su significado.", "audio_text": "She doesn''t work on Sundays."}'::jsonb, '{"text": "Ella no trabaja los domingos."}'::jsonb, '["Ella trabaja los domingos.", "Ella no trabaja nunca.", "Ella no puede trabajar los domingos."]'::jsonb, NULL),
('00000003-0014-0005-0008-000000000001', '00000002-0000-0000-0014-000000000005', 8, 'listening', '{"text": "Escucha la oración y selecciona su significado.", "audio_text": "I am a teacher and I live in Quito."}'::jsonb, '{"text": "Soy maestro/a y vivo en Quito."}'::jsonb, '["Soy maestro/a y vivo en México.", "Estoy en Quito porque soy maestro/a.", "Vivo en Quito pero no soy maestro/a."]'::jsonb, NULL);
INSERT INTO lessons (id, module_id, unit_id, order_index, slug, title, description, lesson_type, xp_reward, estimated_minutes, theory_content, is_published) VALUES
('00000002-0000-0000-0015-000000000001', '00000001-0000-0000-0000-000000000015', '00000000-0000-0000-0001-000000000001', 1, 'presentate-en-voz-alta', '{"es": "Preséntate en Voz Alta", "en": "Introduce Yourself Out Loud"}'::jsonb, '{"es": "Practica diciendo presentaciones y saludos en voz alta.", "en": "Practice saying introductions and greetings out loud."}'::jsonb, 'speaking', 30, 12, '{"intro": "En esta lección vas a practicar diciendo en voz alta frases de presentación y saludo que ya aprendiste. Lee cada frase con calma, vocalizando bien cada palabra.", "sections": [{"type": "note", "variant": "tip", "text": "Esta lección es 100% práctica de pronunciación — no presenta vocabulario ni gramática nueva. Lee cada frase en voz alta con calma; si tu navegador no reconoce tu voz, puedes autoevaluarte."}]}'::jsonb, true);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0015-0001-0001-000000000001', '00000002-0000-0000-0015-000000000001', 1, 'speaking', '{"text": "Lee en voz alta esta presentación."}'::jsonb, '{"text": "Good morning! My name is Laura.", "accepted": ["Good morning! My name is Laura.", "Good morning, my name is Laura."]}'::jsonb, NULL, NULL),
('00000003-0015-0001-0002-000000000001', '00000002-0000-0000-0015-000000000001', 2, 'speaking', '{"text": "Lee en voz alta esta respuesta."}'::jsonb, '{"text": "Nice to meet you too!", "accepted": ["Nice to meet you too!", "Nice to meet you too"]}'::jsonb, NULL, NULL),
('00000003-0015-0001-0003-000000000001', '00000002-0000-0000-0015-000000000001', 3, 'speaking', '{"text": "Responde en voz alta a esta pregunta: What''s your name?"}'::jsonb, '{"text": "My name is Carlos.", "accepted": ["My name is Carlos.", "My name is Carlos"]}'::jsonb, NULL, NULL),
('00000003-0015-0001-0004-000000000001', '00000002-0000-0000-0015-000000000001', 4, 'speaking', '{"text": "Responde en voz alta a esta pregunta: Where are you from?"}'::jsonb, '{"text": "I''m from Mexico.", "accepted": ["I''m from Mexico.", "I am from Mexico.", "I''m from Mexico"]}'::jsonb, NULL, NULL),
('00000003-0015-0001-0005-000000000001', '00000002-0000-0000-0015-000000000001', 5, 'speaking', '{"text": "Responde en voz alta a esta pregunta: How old are you?"}'::jsonb, '{"text": "I''m twenty years old.", "accepted": ["I''m twenty years old.", "I am twenty years old."]}'::jsonb, NULL, NULL),
('00000003-0015-0001-0006-000000000001', '00000002-0000-0000-0015-000000000001', 6, 'speaking', '{"text": "Lee en voz alta esta despedida."}'::jsonb, '{"text": "See you later! Take care!", "accepted": ["See you later! Take care!", "See you later, take care!"]}'::jsonb, NULL, NULL),
('00000003-0015-0001-0007-000000000001', '00000002-0000-0000-0015-000000000001', 7, 'speaking', '{"text": "Lee en voz alta esta frase de cortesía."}'::jsonb, '{"text": "Thank you very much.", "accepted": ["Thank you very much.", "Thank you very much"]}'::jsonb, NULL, NULL),
