INSERT INTO lessons (id, module_id, unit_id, order_index, slug, title, description, lesson_type, xp_reward, estimated_minutes, theory_content, is_published) VALUES
('00000002-0000-0000-0015-000000000002', '00000001-0000-0000-0000-000000000015', '00000000-0000-0000-0001-000000000001', 2, 'preguntas-y-respuestas-cortas', '{"es": "Preguntas y Respuestas Cortas", "en": "Questions and Short Answers"}'::jsonb, '{"es": "Practica diciendo preguntas y respuestas cortas en voz alta.", "en": "Practice saying questions and short answers out loud."}'::jsonb, 'speaking', 30, 12, '{"intro": "Practicarás preguntas con palabras interrogativas, con do/does, y con can — además de sus respuestas cortas. Cuida la entonación ascendente típica de las preguntas en inglés.", "sections": [{"type": "note", "variant": "tip", "text": "Esta lección es 100% práctica de pronunciación — no presenta vocabulario ni gramática nueva. Lee cada frase en voz alta con calma; si tu navegador no reconoce tu voz, puedes autoevaluarte."}]}'::jsonb, true);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
