('00000002-0000-0000-0015-000000000003', '00000001-0000-0000-0000-000000000015', '00000000-0000-0000-0001-000000000001', 3, 'habla-de-tu-familia', '{"es": "Habla de tu Familia", "en": "Talk About Your Family"}'::jsonb, '{"es": "Practica diciendo oraciones sobre tu familia en voz alta.", "en": "Practice saying sentences about your family out loud."}'::jsonb, 'speaking', 30, 12, '{"intro": "Lee en voz alta estas oraciones sobre familia. Presta atención a la -s de la tercera persona (has, doesn''t) y a los pronombres posesivos (his, her, my).", "sections": [{"type": "note", "variant": "tip", "text": "Esta lección es 100% práctica de pronunciación — no presenta vocabulario ni gramática nueva. Lee cada frase en voz alta con calma; si tu navegador no reconoce tu voz, puedes autoevaluarte."}]}'::jsonb, true);
