('00000002-0000-0000-0015-000000000005', '00000001-0000-0000-0000-000000000015', '00000000-0000-0000-0001-000000000001', 5, 'repaso-oral-general', '{"es": "Repaso Oral General", "en": "General Speaking Review"}'::jsonb, '{"es": "Repasa en voz alta toda la gramática A1: to be, there is/are, do/does, can y más.", "en": "Review all A1 grammar out loud: to be, there is/are, do/does, can, and more."}'::jsonb, 'speaking', 30, 12, '{"intro": "Esta última lección de producción oral combina toda la gramática del curso. Es el repaso final de pronunciación del nivel A1 — ¡felicidades por llegar hasta aquí!", "sections": [{"type": "note", "variant": "tip", "text": "Esta lección es 100% práctica de pronunciación — no presenta vocabulario ni gramática nueva. Lee cada frase en voz alta con calma; si tu navegador no reconoce tu voz, puedes autoevaluarte."}]}'::jsonb, true);
